for (int i = 0; i < busy.size(); ++i) {
    if (busy[i].first >= limit || busy[i].second <= 0) continue;
    int start = std::max(0, busy[i].first);
    int end = std::min(limit - 1, busy[i].second - 1);
    for (int j = i + 1; j < busy.size(); ++j) {
        if (busy[j].first <= start || busy[j].second >= end) continue;
        if (start > busy[j].first && end < busy[j].second) {
            start = std::max(start, busy[j].first);
            end = std::min(end, busy[j].second);
        }
    }
    free_slots.push_back({start, end});
}
if (free_slots.empty() || limit <= 0) return {};
for (int i = 1; i < free_slots.size(); ++i) {
    if (free_slots[i - 1].second >= free_slots[i].first) return {};
}
return free_slots;

